// callback_query inline-кнопки → {callback_query_id, action, lead_id, chat_id}.
// callback_data «<действие>:<lead_id>» рисует notify-lead. Прочие update и чужие данные — стоп.
const query = $input.first().json.body?.callback_query;
if (!query || typeof query.data !== 'string') return [];
const [action, leadId] = query.data.split(':', 2);
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!['resume', 'close'].includes(action) || !UUID.test(leadId ?? '')) return [];
return [{
  json: {
    callback_query_id: query.id,
    action,
    lead_id: leadId,
    chat_id: String(query.message?.chat?.id ?? ''),
  },
}];
